using ghidra.util.task;

class DataTableModel : AddressBasedTableModel<DataRowObject> {

	static readonly int ADDRESS_COL_WIDTH = 50;
	static readonly int SIZE_COL_WIDTH = 30;

	static readonly int DATA_COL = 0;
	static readonly int LOCATION_COL = 1;
	static readonly int TYPE_COL = 2;
	static readonly int SIZE_COL = 3;

	private DataWindowPlugin plugin;
	private AddressMapImpl addressMap;
	private Listing listing;
	private AddressSet restrictedAddresses;

	DataTableModel(DataWindowPlugin plugin) : base("Data", plugin.getTool(), null, null)
    {
		this.plugin = plugin;
	}

	/* @Override */
	protected TableColumnDescriptor<DataRowObject> createTableColumnDescriptor() {
		TableColumnDescriptor<DataRowObject> descriptor = new();

		descriptor.addVisibleColumn(new DataValueTableColumn());
		descriptor.addVisibleColumn(
			DiscoverableTableUtils.adaptColumForModel(this, new AddressTableColumn()), 1, true);
		descriptor.addVisibleColumn(new TypeTableColumn());
		descriptor.addVisibleColumn(new SizeTableColumn());

		return descriptor;
	}

	void reload(Program newProgram) {
		this.setProgram(newProgram);
		restrictedAddresses = plugin.getLimitedAddresses();
		if (newProgram != null) {
			addressMap = new AddressMapImpl();
			listing = newProgram.getListing();
		}
		else {
			addressMap = null;
			listing = null;
		}
		reload();
	}

	private int getKeyCount() {
		if (listing == null) {
			return 0;
		}
		return (int) listing.getNumDefinedData();
	}

	/* @Override */
	protected void doLoad(Accumulator<DataRowObject> accumulator, TaskMonitor monitor)
    {

		if (listing == null) {
			return;
		}

		monitor.initialize(getKeyCount());
		int progress = 0;
		LongIterator it = new DataKeyIterator();
		while (it.hasNext()) {
			monitor.setProgress(progress++);
			monitor.checkCancelled();
			long key = it.next();
			if (filterAccepts(key)) {
				accumulator.add(new DataRowObject(key, addressMap));
			}
		}
	}

	private bool filterAccepts(long key) {
		if (listing == null || addressMap == null) {
			return false;
		}

		Data data = listing.getDataAt(addressMap.decodeAddress(key));
		string displayName = data.getDataType().getDisplayName();
		if (restrictedAddresses != null) {
			Address minAddress = data.getMinAddress();
			return plugin.isTypeEnabled(displayName) && restrictedAddresses.contains(minAddress);
		}
		return plugin.isTypeEnabled(displayName);
	}

	void dataAdded(Address addr) {
		Data data = listing.getDataAt(addr);
		if (data != null) {
			long key = addressMap.getKey(addr);
			if (filterAccepts(key)) {
				addObject(new DataRowObject(key, addressMap));
			}
		}
	}

	void dataRemoved(Address addr) {
		removeObject(new DataRowObject(addressMap.getKey(addr), addressMap));
	}

	/* @Override */
	public ProgramSelection getProgramSelection(int[] rows) {
		AddressSet set = new AddressSet();
		foreach (int element in rows) {
			DataRowObject rowObject = getRowObject(element);
			Data data = listing.getDataAt(rowObject.getAddress());
			if (data != null) {
				set.addRange(data.getMinAddress(), data.getMaxAddress());
			}
		}
		return new ProgramSelection(set);
	}

	/* @Override */
	public Address getAddress(int row) {
		return getRowObject(row).getAddress();
	}

	private Data getDataForRowObject(DataRowObject t) {
		return listing.getDataAt(t.getAddress());
	}

//==================================================================================================
// Inner Classes
//==================================================================================================

	private class DataKeyIterator : LongIterator {
		private DataIterator it;

		DataKeyIterator() {
			it = listing.getDefinedData(getProgram().getMemory(), true);
		}

		/* @Override */
		public bool hasNext() {
			if (it == null || getProgram() == null) {
				return false;
			}
			return it.hasNext();
		}

		/* @Override */
		public long next() {
			Data data = it.next();
			if (addressMap != null) {
				return addressMap.getKey(data.getMinAddress());
			}
			return 0;
		}

		/* @Override */
		public bool hasPrevious() {
			return false;
		}

		/* @Override */
		public long previous() {
			return -1;
		}
	}

	private class DataValueTableColumn : AbstractProgramBasedDynamicTableColumn<DataRowObject, string> {

		/* @Override */
		public string getColumnName() {
			return "Data";
		}

		/* @Override */
		public string getColumnDescription() {
			return "Data value";
		}

		/* @Override */
		public string getValue(DataRowObject rowObject, Settings settings, Program p,
				ServiceProvider provider)
    {
			Data data = getDataForRowObject(rowObject);
			if (data == null) {
				return null;
			}
			DataType dt = data.getDataType();
			// NOTE: settings definitions are not currently provided by column since every 
			// data type could have a unique set of supported settings
			return dt.getRepresentation(data, settings, data.getLength());
		}
	}

	private class TypeTableColumn : AbstractProgramBasedDynamicTableColumn<DataRowObject, string> {

		/* @Override */
		public string getColumnName() {
			return "Type";
		}

		/* @Override */
		public string getValue(DataRowObject rowObject, Settings settings, Program p,
				ServiceProvider provider)
    {
			Data data = getDataForRowObject(rowObject);
			if (data == null) {
				return null;
			}

			return data.getDataType().getDisplayName();
		}

	}

	private class SizeTableColumn : AbstractProgramBasedDynamicTableColumn<DataRowObject, Integer> {

		/* @Override */
		public string getColumnName() {
			return "Size";
		}

		/* @Override */
		public Integer getValue(DataRowObject rowObject, Settings settings, Program p,
				ServiceProvider provider)
    {
			Data data = getDataForRowObject(rowObject);
			if (data == null) {
				return null;
			}

			return Integer.valueOf(data.getLength());
		}

	}
}
